#define PI 3.1415926538

float rnd(vec2 p, float n) {
    return fract(abs(sin(p.x*123.4+p.y*432.1)*(p.x*3.7+p.x*p.y*4.5+256.7+n*654.3)+n*321.1));
}

mat2 rot(float a) {
    float c = cos(a);
    float s = sin(a);
    return mat2(c,s,s,-c);
}

vec3 cmap(float v, vec3 s) {
    return clamp(vec3(v,v,v)-s,0.0,1.0);
}

float focus(float v, float r, float p1, float p2) {
    return pow(pow(p1,abs(r-v)+0.001),p2);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv0 = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;
    float t = 0.0;
    const float n = 20.0;
    // inner ring
    for(float r = 0.6;r<=0.9;r+=0.0025) {
        vec2 rv = vec2(r,r);
        vec2 uv = rot(iTime*r*8.0+rnd(rv,1.0)*5.0)*uv0;
        float l = pow(length(uv+sin(iTime)*vec2(rnd(rv,2.0),rnd(rv,3.0))/10.0),2.0);
        float a = atan(uv.y, uv.x);
        float q = floor((a/PI+1.0)*n);
        float v = focus(l,r,0.1,30.0);
        v*=(sin(a*n))/2.0;
        v=max(v,0.0);
        if(rnd(vec2(q,r), 1.0)>0.4) {
            v = 0.0;
        }
        t+=v;
    }
    //outer sparks
    for(float o=0.0;o<=PI;o+=0.2)
    for(float r = 0.7;r<=0.85;r+=0.025) {
        vec2 rv = vec2(r,o);
        float a = atan(uv0.y, uv0.x)+o+rnd(rv,6.0)*sin(iTime*10.0*(1.0+rnd(rv,7.0)))/40.0;
        a = mod(a,PI);
        float l = length(uv0)-0.15;
        float v = focus(r,l*cos(a),0.001,40.0) * a;
        v *= sin(a*n*(1.0+rnd(rv,5.0))-25.0*iTime);
        v = abs(v) * pow(abs(1.0-a),3.6);
        t+=v*16.0;
    }
    t=min(t*3.0,3.0);
    vec3 col = cmap(t,vec3(0.0,1.0,2.0));
    if(length(uv0)>0.75) {
        col+=vec3(0.3,0.3,0.3);
    } else {
        col+=vec3(0.0,0.4,0.7);
    }
    fragColor = vec4(col,1.0);
}
